/**
 * VerdictCard — displays full analysis result with high-fidelity telemetry styling.
 * Magic UI & Unlumen AI aesthetic: Frosted specular card, glowing risk indicators,
 * clean typography, and explainability tags.
 *
 * All threat decisions strictly generated by the backend API.
 */
import type { AnalysisResponse } from '../../types/api';
import RiskBadge from './RiskBadge';

interface Props {
  result: AnalysisResponse;
  onReport?: () => void;
}

const RISK_THEMES: Record<string, { bar: string; glow: string; text: string }> = {
  red: {
    bar: 'from-red-500 via-rose-500 to-pink-500',
    glow: 'shadow-[0_0_16px_rgba(239,68,68,0.5)]',
    text: 'text-rose-400',
  },
  amber: {
    bar: 'from-amber-400 via-yellow-400 to-orange-400',
    glow: 'shadow-[0_0_16px_rgba(245,158,11,0.5)]',
    text: 'text-amber-400',
  },
  green: {
    bar: 'from-emerald-400 via-teal-400 to-cyan-400',
    glow: 'shadow-[0_0_16px_rgba(52,211,153,0.5)]',
    text: 'text-emerald-400',
  },
};

export default function VerdictCard({ result, onReport }: Props) {
  const theme = RISK_THEMES[result.risk] ?? RISK_THEMES.amber;
  const scorePct = Math.round(result.score * 100);

  return (
    <article
      aria-label="Verdict details"
      className="relative rounded-3xl glass-strong border border-white/10 p-6 space-y-6 w-full max-w-lg mx-auto shadow-2xl float-in overflow-hidden"
    >
      {/* Subtle top specular accent border */}
      <div className="absolute top-0 inset-x-0 h-[1px] bg-gradient-to-r from-transparent via-white/20 to-transparent" />

      {/* Header bar */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <RiskBadge risk={result.risk} score={result.score} size="lg" />
        <div className="flex items-center gap-2">
          <span className="px-2.5 py-1 rounded-full bg-slate-900/60 border border-white/5 text-[11px] font-mono tracking-wider text-slate-400 uppercase">
            {result.kind} · {result.model_version}
          </span>
        </div>
      </div>

      {/* Threat Confidence Meter */}
      <div className="space-y-2 p-4 rounded-2xl bg-slate-950/40 border border-white/5">
        <div className="flex items-center justify-between text-xs">
          <span className="font-medium text-slate-400 flex items-center gap-1.5">
            <span className="w-1.5 h-1.5 rounded-full bg-slate-400" />
            Threat Confidence Index
          </span>
          <span className={`font-mono font-bold text-sm ${theme.text}`}>
            {scorePct}%
          </span>
        </div>
        <div
          className="h-2.5 rounded-full bg-slate-900 overflow-hidden p-0.5 border border-white/5"
          role="progressbar"
          aria-valuenow={scorePct}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-label="Risk score percentage"
        >
          <div
            className={`h-full rounded-full bg-gradient-to-r transition-all duration-1000 ease-out ${theme.bar} ${theme.glow}`}
            style={{ width: `${Math.max(scorePct, 4)}%` }}
          />
        </div>
      </div>

      {/* Analyzed Destination or Domain */}
      {result.domain && (
        <div className="flex items-center justify-between p-3 rounded-2xl bg-slate-950/30 border border-white/5 text-xs">
          <span className="text-slate-400">Target host:</span>
          <code className="font-mono text-cyan-300 font-medium px-2 py-0.5 rounded-lg bg-cyan-950/40 border border-cyan-800/30">
            {result.domain}
          </code>
        </div>
      )}

      {/* Actionable Defense Advisement */}
      <div className="relative rounded-2xl bg-gradient-to-br from-indigo-950/40 via-blue-950/30 to-slate-950/50 border border-blue-500/20 p-4 shadow-inner">
        <div className="flex items-center gap-2 mb-1.5">
          <div className="w-5 h-5 rounded-lg bg-blue-500/20 flex items-center justify-center text-blue-400">
            <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m0-10.036A11.959 11.959 0 0 1 3.598 6 11.99 11.99 0 0 0 3 9.75c0 5.592 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.31-.21-2.57-.598-3.75h-.152c-3.196 0-6.1-1.25-8.25-3.286Zm0 13.036h.008v.008H12v-.008Z" />
            </svg>
          </div>
          <span className="text-[11px] font-semibold uppercase tracking-wider text-blue-300">
            Recommended Action
          </span>
        </div>
        <p className="text-xs sm:text-sm text-slate-200 leading-relaxed font-normal">
          {result.advice}
        </p>
      </div>

      {/* Evidence-Backed Explainability Reasons */}
      {result.reasons.length > 0 && (
        <section aria-label="Detection reasons" className="space-y-3">
          <h3 className="text-[11px] font-mono uppercase tracking-widest text-slate-400 flex items-center gap-2">
            <span className="w-1.5 h-1.5 rounded-full bg-cyan-400" />
            Explainable Detection Telemetry ({result.reasons.length})
          </h3>
          <div className="space-y-2">
            {result.reasons.map((r) => (
              <div
                key={r.code}
                className="flex items-start justify-between gap-3 p-3 rounded-2xl bg-slate-950/40 border border-white/5 hover:border-white/10 transition-colors"
              >
                <div className="flex items-start gap-2.5">
                  <div className="w-1.5 h-1.5 rounded-full bg-indigo-400 shrink-0 mt-1.5" />
                  <p className="text-xs sm:text-sm text-slate-300 leading-normal">
                    {r.text}
                  </p>
                </div>
                <span className="shrink-0 font-mono text-[10px] text-slate-400 px-2 py-0.5 rounded-md bg-white/5 border border-white/10">
                  {r.code}
                </span>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Threat Tags */}
      {result.tags.length > 0 && (
        <div className="flex flex-wrap gap-2 pt-1" aria-label="Risk classification tags">
          {result.tags.map((tag) => (
            <span
              key={tag}
              className="text-[11px] font-mono px-2.5 py-1 rounded-full bg-slate-900/80 text-cyan-300/90 border border-cyan-500/20 shadow-sm"
            >
              #{tag}
            </span>
          ))}
        </div>
      )}

      {/* Forensic Metadata footer */}
      <div className="pt-2 border-t border-white/5 flex items-center justify-between text-[11px] text-slate-500 font-mono">
        <span>Check ID:</span>
        <code className="text-slate-400 select-all hover:text-cyan-300 transition-colors">
          {result.check_id.slice(0, 8)}...{result.check_id.slice(-6)}
        </code>
      </div>

      {/* Report Action Button */}
      {onReport && (
        <button
          onClick={onReport}
          className="w-full btn-glow py-3.5 px-4 rounded-2xl font-semibold text-sm text-white flex items-center justify-center gap-2 cursor-pointer transition-all"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126ZM12 15.75h.008v.008H12v-.008Z" />
          </svg>
          Escalate Threat Report to Campus Security
        </button>
      )}
    </article>
  );
}
